Here is a sample implementation of the Minimum Spanning Tree (MST) algorithm using Kruskal's algorithm in C++:
```
#include <iostream>
#include <vector>
#include <queue>
#include <utility>
using namespace std;

struct Edge {
  int u, v;
  double weight;
};

bool compareEdges(const Edge& e1, const Edge& e2) {
  return e1.weight < e2.weight;
}

void kruskalMST(vector<Edge>& edges) {
  vector<int> parent(edges.size());
  for (int i = 0; i < parent.size(); i++) {
    parent[i] = i;
  }

  priority_queue<Edge, vector<Edge>, compareEdges> pq;
  for (const auto& edge : edges) {
    pq.push(edge);
  }

  int numEdges = 0;
  while (!pq.empty()) {
    Edge edge = pq.top();
    int u = findParent(parent, edge.u);
    int v = findParent(parent, edge.v);

    if (u != v) {
      parent[u] = v;
      numEdges++;
      cout << "(" << edge.u << ", " << edge.v << ") weight: " << edge.weight << endl;
    }

    pq.pop();
  }
}

int findParent(vector<int>& parent, int node) {
  if (parent[node] != node) {
    return findParent(parent, parent[node]);
  } else {
    return node;
  }
}

int main() {
  vector<Edge> edges = {{0, 1, 2}, {1, 2, 3}, {2, 3, 4}, {3, 4, 5}};
  kruskalMST(edges);
  return 0;
}
```
This implementation uses a priority queue to store the edges in non-decreasing order of their weights. It then iteratively extracts the minimum weight edge from the queue and checks if it connects two disjoint sets. If it does, it merges the two sets by setting the parent of one set to be the other. The number of edges in the MST is kept track of using a variable `numEdges`.

The `findParent` function is used to find the representative element of a connected component in the forest. It recursively searches for the parent of a node until it reaches the root, which is itself. This function is needed because the Kruskal algorithm modifies the parent array during the course of its execution.

This implementation assumes that the input graph is represented as an adjacency list, where each element in the list contains a pair of nodes and their weight between them. The `kruskalMST` function takes an edge list as input and outputs the MST as a series of connected edges.

