The Union-Find data structure, also known as Disjoint Set Union (DSU), is a data structure that tracks a set of elements partitioned into disjoint subsets. It supports two main operations efficiently:

1. **Find**: Determine which subset a particular element is in. This can be used to check if two elements are in the same subset.
2. **Union**: Join two subsets into a single subset.

Path compression is an optimization technique that flattens the structure of the tree whenever `find` is called, ensuring that every node points directly to the root. This leads to a nearly constant time complexity for both operations.

Here is a Python implementation of the Union-Find data structure with path compression:

```python
class UnionFind:
    def __init__(self, size):
        # Initialize the parent array
        self.parent = [i for i in range(size)]
        # Initialize the rank array for union by rank
        self.rank = [1] * size

    def find(self, p):
        # Path compression
        if self.parent[p] != p:
            self.parent[p] = self.find(self.parent[p])  # Recursively find the root and compress the path
        return self.parent[p]

    def union(self, p, q):
        rootP = self.find(p)
        rootQ = self.find(q)

        if rootP != rootQ:
            # Union by rank
            if self.rank[rootP] > self.rank[rootQ]:
                self.parent[rootQ] = rootP
            elif self.rank[rootP] < self.rank[rootQ]:
                self.parent[rootP] = rootQ
            else:
                self.parent[rootQ] = rootP
                self.rank[rootP] += 1

    def connected(self, p, q):
        return self.find(p) == self.find(q)

    def get_parent(self, p):
        return self.find(p)

# Example usage
if __name__ == "__main__":
    uf = UnionFind(10)  # Create a Union-Find with 10 elements

    uf.union(1, 2)
    uf.union(2, 3)
    uf.union(4, 5)

    print(uf.connected(1, 3))  # True
    print(uf.connected(1, 4))  # False

    uf.union(3, 4)
    print(uf.connected(1, 4))  # True
