```typescript
class PriorityQueue {
  private heap: number[];

  constructor() {
    this.heap = [];
  }

  /**
   * Inserts a new element into the priority queue.
   * 
   * @param value The value to insert.
   */
  enqueue(value: number): void {
    this.heap.push(value);
    this.heapifyUp(this.heap.length - 1); // Restore heap property after insertion
  }

  /**
   * Retrieves and removes the element with the highest priority (lowest value).
   * 
   * @returns The highest priority element, or undefined if the queue is empty.
   */
  dequeue(): number | undefined {
    if (this.isEmpty()) return undefined;

    const min = this.heap[0]; // Get root (min element)
    this.heap[0] = this.heap.pop()!; // Replace root with last element
    this.heapifyDown(0); // Restore heap property after removal
    return min;
  }

  /**
   * Checks if the priority queue is empty.
   * 
   * @returns True if empty, false otherwise.
   */
  isEmpty(): boolean {
    return this.heap.length === 0;
  }

  /**
   * Retrieves the element with the highest priority (lowest value) without removing it.
   * 
   * @returns The highest priority element, or undefined if the queue is empty.
   */
  peek(): number | undefined {
    return this.isEmpty() ? undefined : this.heap[0];
  }

  /**
   * Restores heap property by moving an element up the heap.
   * 
   * @param index The index of the element to move up.
   */
  private heapifyUp(index: number): void {
    let parentIndex = Math.floor((index - 1) / 2);

    while (index > 0 && this.heap[index] < this.heap[parentIndex]) {
      // Swap elements
      [this.heap[index], this.heap[parentIndex]] = [this.heap[parentIndex], this.heap[index]];
      index = parentIndex;
      parentIndex = Math.floor((index - 1) / 2);
    }
  }

  /**
   * Restores heap property by moving an element down the heap.
   * 
   * @param index The index of the element to move down.
   */
  private heapifyDown(index: number): void {
    let leftChildIndex = 2 * index + 1;
    let rightChildIndex = 2 * index + 2;
    let smallestIndex = index;

    if (leftChildIndex < this.heap.length && this.heap[leftChildIndex] < this.heap[smallestIndex]) {
      smallestIndex = leftChildIndex;
    }

    if (rightChildIndex < this.heap.length && this.heap[rightChildIndex] < this.heap[smallestIndex]) {
      smallestIndex = rightChildIndex;
    }

    if (smallestIndex !== index) {
      // Swap elements
      [this.heap[index], this.heap[smallestIndex]] = [this.heap[smallestIndex], this.heap[index]];
      this.heapifyDown(smallestIndex); // Recursively restore heap property
    }
  }
}

