use std::collections::HashMap;
use std::collections::HashSet;

// Define a struct to hold our results
struct AnagramGroup {
    // This holds the sorted letters of the key word
    sorted_key: String,
    // And this holds all the words that are anagrams of the key word
    anagrams: HashSet<String>,
}

fn find_anagrams(words: Vec<String>) -> HashMap<String, AnagramGroup> {

    // Create a new HashMap to hold our results
    let mut result_map = HashMap::new();

    // Iterate over each string in our input vector
    for word in words {
        // Sort the letters of this word and add it as a key to our result map
        let sorted_key = word.chars().sorted().collect::<String>();
        let anagrams = words.iter()
                            .filter(|&&w| w.chars().sorted() == Some(sorted_key))
                            .map(|s| s.to_string())
                            .collect::<HashSet<String>>();

        // Add this group of anagrams to our result map
        result_map.insert(sorted_key, AnagramGroup{ sorted_key, anagrams });
    }

    // Return the resulting map of anagram groups
    result_map
}
