```c
#include <stdio.h>
#include <stdlib.h>

// Define the structure for a disjoint set node
typedef struct DisjointSetNode {
    int id;
    int parent;
    int size; // Size of the subset represented by this node
} DisjointSetNode;

// Create a new disjoint set with n nodes (initial capacity)
int createDisjointSet(int n) {
    DisjointSetNode* ds = malloc(n * sizeof(DisjointSetNode));
    for (int i = 0; i < n; i++) {
        ds[i].id = i;
        ds[i].parent = i; // Initialize each node as its own parent
        ds[i].size = 1;
    }
    return n; // Return the number of nodes created
}

// Find the root (representative) of a node and return its ID
int find(int id, DisjointSetNode* ds) {
    while (ds[id].parent != id) {
        id = ds[id].parent;
    }
    return id; // Return the root ID
}

// Union two disjoint sets by finding their representatives and updating parent pointers
void unionSets(int id1, int id2, DisjointSetNode* ds) {
    int rep1 = find(id1, ds);
    int rep2 = find(id2, ds);

    if (rep1 != rep2) {
        ds[rep1].parent = rep2;
        ds[rep2].size += ds[rep1].size; // Update size of the larger set
    }
}

// Get the size of a disjoint set represented by its root node
int getSize(int id, DisjointSetNode* ds) {
    return ds[find(id, ds)].size;
}

int main() {
    int n = createDisjointSet(5); // Create a disjoint set with 5 nodes

    // Initialize node IDs and parents
    for (int i = 0; i < n; i++) {
        printf("Node %d: ID=%d, Parent=%d, Size=%d\n", i, ds[i].id, ds[i].parent, ds[i].size);
    }

    // Perform union operations
    unionSets(0, 2, ds);
    unionSets(3, 4, ds);

    // Get the size of disjoint sets
    printf("Set 0 Size: %d\n", getSize(0, ds));
    printf("Set 2 Size: %d\n", getSize(2, ds));

    return 0;
}
```

